/* USDT 余额钱包与会员推广新口径（加载于 mcn-business.js 之后）。
   有效推广 = 直推会员累计充值达到后台门槛；推广等级 = 有效会员数；会员分红 = 直推会员确认完成的消费额 × 等级比例；
   分红每日 00:00 结算前一天并自动入账到推广员余额钱包。钱包以 USDT 计价；首期商品也以 USDT 定价（汇率为 1），启用其他定价币种后按后台汇率换算。 */
const WP={tab:'all'};
const WP_FROZEN=['待审核','待执行','在途','结果未知','明确失败'];
const WP_TYPES=['充值','消费','退款','推广分红','分红冲回','提现'];
const wpR=n=>uncents(cents(n));
const wpFloor=n=>uncents(Math.floor(Math.round(Number(n||0)*1e6)/1e4));
function wpNum(n){return Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function wpU(n){return wpNum(n)+' USDT';}
function wpDB(){if(!db)return null;if(!db.walletV1){db.walletV1={version:1,settings:{rate:1,rechargeMin:10,withdrawMin:10,withdrawFee:1,principalWithdrawable:false,networks:['TRC20','ERC20']},entries:[],recharges:[],withdrawals:[],accruals:[],runs:[{id:'WPRUN-'+TODAY,day:TODAY,cutoff:pd8AddDays(TODAY,-1),supplement:false,actor:'系统 00:00 自动日结',at:TODAY+'T00:00:00Z',lines:[],total:0,count:0}],logs:[],refundBaseline:(db.refunds||[]).filter(r=>r.status==='已退款').map(r=>r.id),createdAt:TODAY};}
 const W=db.walletV1;for(const k of ['entries','recharges','withdrawals','accruals','runs','logs','refundBaseline'])W[k]||=[];return W;}
function wpMigratePromotion(){const d=db?.mcnV1;if(!d||d.wpModel)return;d.wpModel=1;const s=d.settings;if(!('rechargeThreshold' in s))s.rechargeThreshold=100;if(!('dividendSource' in s))s.dividendSource='wallet';if(s.version==='MCN-RULE-DEMO-1'){s.validDays=0;s.bindingDays=0;s.version='MCN-RULE-DEMO-2';}
 for(const [id,m,oldPct,newPct] of [['PROMO-L1',0,10,1],['PROMO-L2',3,15,1.5],['PROMO-L3',10,20,2]]){const l=d.levels.find(x=>x.id===id);if(l&&l.minMembers===m&&l.pct===oldPct)l.pct=newPct;}for(const l of d.levels)l.minSpend=0;}
const wpEnsureBase=mcnEnsure;mcnEnsure=function(){const out=wpEnsureBase();if(db?.mcnV1){wpMigratePromotion();wpDB();}return out;};
function wpRate(){return Number(wpDB().settings.rate)||1;}
function wpToUSDT(d,rate=wpRate()){return wpR(Number(d||0)/rate);}
function wpLog(action,object,reason,actor){wpDB().logs.unshift({id:uid('WPLOG'),action,object,reason,actor,at:mcnNow()});audit('余额钱包 · '+action,object,reason||'');}
function wpPost(user,type,principal,cash,meta={}){const e={id:uid('WPLED'),user,type,principal:wpR(principal),cash:wpR(cash),amount:addMoney(principal,cash),at:mcnNow(),day:TODAY,...meta};wpDB().entries.unshift(e);return e;}
function wpBalance(user){const W=wpDB(),es=W.entries.filter(x=>x.user===user),ws=W.withdrawals.filter(w=>w.user===user&&WP_FROZEN.includes(w.status)),principal=sumMoney(es,'principal'),cash=sumMoney(es,'cash'),fp=sumMoney(ws,'principal'),fc=sumMoney(ws,'cash'),freeP=addMoney(principal,-fp),freeC=addMoney(cash,-fc);
 return {principal,cash,total:addMoney(principal,cash),frozen:addMoney(fp,fc),freeP,freeC,spendable:Math.max(0,addMoney(freeP,freeC)),withdrawable:Math.max(0,W.settings.principalWithdrawable?addMoney(freeP,freeC):freeC)};}
function wpRecharged(user){return sumMoney(wpDB().recharges.filter(r=>r.user===user&&r.status==='已到账'),'amount');}
function wpBizDay(){const W=db?.walletV1;return W?.clockDay&&W.clockDay>TODAY?W.clockDay:TODAY;}
function wpNextRun(){const last=wpDB().runs.filter(r=>!r.supplement).map(r=>r.day).sort().at(-1)||TODAY,base=last>TODAY?last:TODAY,day=pd8AddDays(base,1);return {day,last:base,done:false,label:day.slice(5)+' 00:00'};}
function wpMoney2(n){const v=Number(n||0);return v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}

/* ---------- Promotion model ---------- */
mcnReferralFacts=function(r){const s=mcnDB().settings,u=getBy('users',r.user),recharged=wpRecharged(r.user),threshold=Number(s.rechargeThreshold??100),validUser=u?.status==='正常'&&(!s.requireAdult||String(u.adult).startsWith('已完成'))&&(!s.requireVerified||!!u.mcnVerified);
 return {spent:recharged,recharged,threshold,validUser,eligible:validUser&&cents(recharged)>=cents(threshold),proofs:wpDB().recharges.filter(x=>x.user===r.user&&x.status==='已到账').map(x=>x.id)};};
mcnEvaluateReferrals=function(){for(const r of mcnDB().referrals){if(r.status==='人工失效')continue;const f=mcnReferralFacts(r),expired=(r.expires&&r.expires<TODAY)||r.forcedExpired;r.spent=f.recharged;r.recharged=f.recharged;r.proofs=f.proofs;
  if(f.eligible||(r.effectiveAt&&f.validUser)){if(!r.effectiveAt){r.effectiveAt=mcnNow();mcnEvent('有效推广',r.id,r.stationId,r.user,'valid:'+r.id);}r.status=expired?'已到期':'有效推广';r.invalidReason='';}
  else{r.status=expired?'已到期':'待达标';r.invalidReason=f.validUser?'累计充值 '+wpNum(f.recharged)+' / '+wpNum(f.threshold)+' USDT':'待平台核验或账号条件未满足';}}};
mcnLevel=function(promoter){mcnEvaluateReferrals();const n=mcnDB().referrals.filter(r=>r.promoter===promoter?.id&&r.status==='有效推广').length;return [...mcnDB().levels].filter(l=>l.status==='启用'&&n>=l.minMembers).sort((a,b)=>b.minMembers-a.minMembers)[0]||mcnDB().levels[0];};
const wpShareBase=mcnShareAmount;mcnShareAmount=(r,kind)=>kind==='promotion'?0:wpShareBase(r,kind);
const wpCaptureBase=mcnCapture;mcnCapture=function(b,o){const out=wpCaptureBase(b,o);if(b.mcnSnapshot)b.mcnSnapshot.promotion=null;return out;};
mcnSyncVipShares=function(){};
function wpAccrualOwner(p){return p.kind==='guild'?mcnDB().guilds.find(g=>g.id===p.owner)?.manager:p.user;}
function wpAccrue(key,src){const W=wpDB(),s=mcnDB().settings,ref=mcnReferral(src.member);if(!ref)return;W.skipped||={};let a=W.accruals.find(x=>x.key===key);
 if(!a){if(W.skipped[key]||!(src.baseD>0))return;const p=mcnDB().promoters.find(x=>x.id===ref.promoter),why=!p||p.status!=='启用'?'推广资格未启用':!s.promotionEnabled?'推广功能关闭':ref.status==='人工失效'?'推广关系已失效':ref.forcedExpired||(ref.expires&&ref.expires<TODAY)?'推广关系已到期':!src.eligibleSource?'消费来源不计入分红':'';if(why){W.skipped[key]=why+' · '+TODAY;return;}const lv=mcnLevel(p);
  a={id:uid('WPACC'),key,kind:src.kind,promoter:p.id,promoterKind:p.kind,owner:wpAccrualOwner(p),member:src.member,order:src.order,bill:src.bill,revenue:src.revenue||'',stationId:src.stationId,pct:lv.pct,level:lv.name,rate:src.rate,walletPaid:!!src.walletPaid,baseD:0,baseUSDT:0,amount:0,settled:0,accruedAt:mcnNow(),accruedDay:wpBizDay(),changedDay:wpBizDay(),status:'待结算',source:'local'};W.accruals.push(a);mcnEvent('消费分红',a.id,a.stationId,a.member,'accrual:'+a.id);}
 const amount=ref.status==='人工失效'?0:wpFloor(wpToUSDT(src.baseD,a.rate)*a.pct/100);a.baseD=src.baseD;a.baseUSDT=wpToUSDT(src.baseD,a.rate);if(cents(amount)!==cents(a.amount)){a.amount=amount;a.changedDay=wpBizDay();}a.hold=!!src.hold;
 a.status=a.hold?'保全中':cents(a.amount)!==cents(a.settled)?'待结算':a.amount>0?'已结算':'无分红';}
function wpSyncAccruals(){const s=mcnDB().settings;mcnEvaluateReferrals();
 for(const r of db.revenues){const b=getBy('bills',r.bill);if(!b||b.c21Type)continue;const o=getBy('orders',r.order||b.order);if(!o)continue;
  wpAccrue('acc:'+r.id,{kind:'服务',member:o.buyer,order:o.id,bill:b.id,revenue:r.id,stationId:r.stationId||b.stationId,baseD:Math.max(0,Number(r.base)||0),rate:b.wpPaid?.rate||wpRate(),walletPaid:!!b.wpPaid,eligibleSource:s.dividendSource==='all'||!!b.wpPaid,hold:b.hold>0||pd8LiveStops(b.id).length>0||db.refunds.some(f=>f.bill===b.id&&fin8RefundLive.includes(f.status))});}
 for(const v of db.vipOrders||[]){if(v.status!=='已支付'||!mcnReferral(v.uid))continue;wpAccrue('acc:vip:'+v.id,{kind:'VIP',member:v.uid,order:v.id,bill:v.id,stationId:v.stationId,baseD:v.refundStatus==='已退款'?0:Number(v.amount)||0,rate:wpRate(),walletPaid:false,eligibleSource:!!s.sourceVip&&s.dividendSource==='all',hold:v.refundStatus==='退款处理中'});}}
function wpSyncRefunds(){const W=wpDB(),skip=new Set(W.refundBaseline);
 for(const x of db.refunds||[]){if(x.status!=='已退款'||skip.has(x.id)||!(Number(x.amount)>0))continue;const key='refund:'+x.id;if(W.entries.some(en=>en.key===key))continue;const o=getBy('orders',x.order);if(!o)continue;
  const b=getBy('bills',x.bill),pay=b?.wpPaid,usdt=pay?.usdt>0&&pay.d>0?Math.min(wpR(pay.usdt*x.amount/pay.d),addMoney(pay.usdt,-(pay.refundedUSDT||0))):wpToUSDT(x.amount,wpRate());if(pay)pay.refundedUSDT=addMoney(pay.refundedUSDT||0,usdt);let principal=0;if(pay?.usdt>0)principal=Math.min(wpR(usdt*pay.principal/pay.usdt),wpR(pay.principal-(pay.refundedPrincipal||0)));if(pay)pay.refundedPrincipal=addMoney(pay.refundedPrincipal||0,principal);
  wpPost(o.buyer,'退款',principal,addMoney(usdt,-principal),{key,ref:x.id,order:o.id,d:x.amount,rate:pay?.rate||wpRate(),note:'订单退款退回余额'});}}
function wpSync(){if(!db?.mcnV1||!db.walletV1)return;wpSyncRefunds();wpSyncAccruals();}
const wpRefreshBase=refreshDerived;refreshDerived=function(){const out=wpRefreshBase();try{wpSync();}catch(err){console.error('wallet sync',err);}return out;};
const wpRevenueBase=pd8UpdateRevenue;pd8UpdateRevenue=function(b){const out=wpRevenueBase(b);wpSync();return out;};
function wpDailyRun(day,actor){const W=wpDB();if(day>(W.clockDay||TODAY))W.clockDay=day;wpSync();const main=W.runs.find(r=>r.day===day&&!r.supplement),items=W.accruals.filter(a=>!a.hold&&a.changedDay<day&&cents(a.amount)!==cents(a.settled)),run={id:uid('WPRUN'),day,cutoff:pd8AddDays(day,-1),supplement:!!main,actor,at:main?mcnNow():day+'T00:00:00Z',lines:[],total:0,count:0};
 const groups=new Map();for(const a of items){if(!a.owner)continue;if(!groups.has(a.owner))groups.set(a.owner,[]);groups.get(a.owner).push(a);}
 for(const [owner,list] of groups){const delta=sumMoney(list,a=>addMoney(a.amount,-a.settled));if(!cents(delta)){for(const a of list){a.settled=a.amount;a.status=a.amount>0?'已结算':'无分红';}continue;}
  const en=wpPost(owner,delta>0?'推广分红':'分红冲回',0,delta,{ref:run.id,note:day+' 00:00 日结 · '+list.length+' 笔'+(run.supplement?'（补跑）':'')});
  for(const a of list){(a.settlements||=[]).push({run:run.id,amount:addMoney(a.amount,-a.settled),entry:en.id});a.settled=a.amount;a.settledAt=run.at;a.status=a.amount>0?'已结算':'无分红';}
  run.lines.push({owner,count:list.length,amount:delta,entry:en.id,accruals:list.map(a=>a.id)});run.total=addMoney(run.total,delta);run.count+=list.length;}
 W.runs.unshift(run);return run;}
function wpAutoRun(){const W=wpDB();if(!W)return;if(!W.runs.some(r=>r.day===TODAY&&!r.supplement))wpDailyRun(TODAY,'系统 00:00 自动日结');}

/* ---------- Commands ---------- */
function wpCommand(action,id='',data={},backend=false){const W=wpDB(),S=W.settings;let actor='';
 if(backend){const a=admin19Require(true);demand(FE.mode==='admin'||ADMIN19.backendDepth>0,'请在运营后台处理管理动作');demand(a.role==='admin','仅总站管理员可处理钱包与日结');actor=a.subject;}
 else if(action==='dailyRun'&&data.demo){actor='演示工具';}
 else{demand(FE.mode!=='admin','用户端动作须使用独立用户端身份');actor=mcnUser().id;}
 const reason=String(data.reason||'').trim();if(backend&&!['dailyRun'].includes(action))demand(reason.length>=4,'后台处理需填写至少4字依据');
 let out=id;const u=!backend&&actor!=='演示工具'?mcnUser():null;
 if(action==='rechargeCreate'){const amount=mcnMoney(data.amount,Math.max(0.01,S.rechargeMin),1000000),network=String(data.network||'TRC20');demand(S.networks.includes(network),'请选择支持的网络');demand(!W.recharges.some(r=>r.user===u.id&&['待支付','结果未知'].includes(r.status)),'你有一笔充值订单尚未完成，请先处理');
  const r={id:uid('WPRC'),user:u.id,amount,network,address:'DEMO-'+network+'-'+uid('ADDR').replace(/[^A-Z0-9]/g,'').slice(-10),status:'待支付',request:uid('WPREQ'),at:mcnNow(),returnTo:String(data.returnTo||''),stationId:u.stationId};W.recharges.unshift(r);out=r.id;}
 else if(action==='rechargeResult'){const r=W.recharges.find(x=>x.id===id);demand(r&&(backend||r.user===u.id),'充值订单不存在');demand(['待支付','结果未知'].includes(r.status),'已完成的充值不能重复确认');demand(['成功','失败','未知'].includes(data.result),'无效的模拟结果');if(r.status==='结果未知')demand(data.query==='on'||data.query===true,'结果未知须查询原充值请求');
  r.status=data.result==='成功'?'已到账':data.result==='失败'?'充值失败':'结果未知';r.queryAt=mcnNow();if(r.status==='已到账'){r.txHash='DEMO-TX-'+uid('TX').replace(/[^A-Z0-9]/g,'').slice(-12);wpPost(r.user,'充值',r.amount,0,{key:'recharge:'+r.id,ref:r.id,note:r.network+' 充值到账'});mcnEvaluateReferrals();}}
 else if(action==='rechargeCancel'){const r=W.recharges.find(x=>x.id===id&&x.user===u.id);demand(r&&r.status==='待支付','只有待支付的充值订单可以取消');r.status='已取消';}
 else if(action==='pay'){const d=db.feDrafts.find(x=>x.id===id&&x.user===u.id);demand(d&&['待支付','支付失败'].includes(d.status),'该订单当前不能使用余额支付');const usdt=wpToUSDT(d.amount),bal=wpBalance(u.id);demand(cents(bal.spendable)>=cents(usdt),'余额不足，请先充值');
  fePay(id);const d2=db.feDrafts.find(x=>x.id===id),o=d2?.order&&getBy('orders',d2.order);demand(d2?.status==='已支付'&&o,'余额支付未完成');const fromP=Math.max(0,Math.min(bal.freeP,usdt)),fromC=addMoney(usdt,-fromP);
  const en=wpPost(u.id,'消费',-fromP,-fromC,{key:'pay:'+d.id,ref:o.id,order:o.id,draft:d.id,d:d.amount,rate:S.rate,note:d.name});const b=getBy('bills',o.currentBill);if(b&&!b.wpPaid)b.wpPaid={usdt,d:d.amount,rate:S.rate,principal:fromP,cash:fromC,entry:en.id,draft:d.id};(o.wpPay||=[]).push({draft:d.id,bill:b?.id||'',usdt,d:d.amount,rate:S.rate,entry:en.id,at:mcnNow()});
  for(const p of db.payments.filter(p=>p.bill===b?.id))p.wpChannel='余额钱包 USDT';refreshDerived();FE.flash='余额支付成功 · 扣除 '+wpU(usdt);out=o.id;}
 else if(action==='withdrawCreate'){const bal=wpBalance(u.id),amount=mcnMoney(data.amount,Math.max(0.01,S.withdrawMin),1000000),fee=Number(S.withdrawFee)||0,network=String(data.network||'TRC20'),address=String(data.address||'').trim();demand(S.networks.includes(network),'请选择支持的网络');demand(/^DEMO-[A-Za-z0-9-]{6,}$/.test(address),'请填写以 DEMO- 开头的演示收款地址，勿输入真实地址');demand(cents(amount)<=cents(bal.withdrawable),'可提现余额不足；充值本金仅可用于消费');demand(cents(amount)>cents(fee),'提现金额须大于手续费');
  const fromC=Math.max(0,Math.min(bal.freeC,amount)),fromP=addMoney(amount,-fromC);const w={id:uid('WPWD'),user:u.id,amount,fee,net:addMoney(amount,-fee),network,address,principal:fromP,cash:fromC,status:'待审核',request:'',attempts:0,at:mcnNow(),stationId:u.stationId};W.withdrawals.unshift(w);out=w.id;}
 else if(action==='withdrawCancel'){const w=W.withdrawals.find(x=>x.id===id);demand(w&&(backend||w.user===u.id),'提现申请不存在');demand(backend?['待审核','待执行','明确失败'].includes(w.status):w.status==='待审核','当前状态不能撤销；在途或结果未知须查询原请求');w.status=backend?'已驳回':'已取消';w.reason=reason||'用户撤销';}
 else if(action==='withdrawReview'){demand(backend,'仅管理员审核提现');const w=W.withdrawals.find(x=>x.id===id);demand(w?.status==='待审核','申请已审核');w.status='待执行';w.reviewReason=reason;}
 else if(action==='withdrawSubmit'){demand(backend,'仅管理员提交出款');const w=W.withdrawals.find(x=>x.id===id);demand(w&&['待执行','明确失败'].includes(w.status),'在途或结果未知须查询原请求，已到账不能再次出款');w.status='在途';w.request=uid('WPOUT');w.attempts++;w.submittedAt=mcnNow();}
 else if(action==='withdrawResult'){demand(backend,'仅管理员查询出款结果');const w=W.withdrawals.find(x=>x.id===id);demand(w&&['在途','结果未知'].includes(w.status),'原出款请求不在可查询状态');demand(['成功','失败','未知'].includes(data.result),'无效回执');
  if(data.result==='成功'){w.status='已到账';w.txHash='DEMO-TX-'+uid('TX').replace(/[^A-Z0-9]/g,'').slice(-12);w.paidAt=mcnNow();wpPost(w.user,'提现',-w.principal,-w.cash,{key:'withdraw:'+w.id,ref:w.id,note:w.network+' 提现 · 手续费 '+wpNum(w.fee)+' · 到账 '+wpNum(w.net)});}else w.status=data.result==='失败'?'明确失败':'结果未知';w.queryAt=mcnNow();}
 else if(action==='settings'){demand(backend,'仅管理员修改钱包设置');const rate=Number(data.rate);demand(Number.isFinite(rate)&&rate>0&&rate<=100000,'汇率须大于0');S.rate=Math.round(rate*10000)/10000;S.rechargeMin=mcnMoney(data.rechargeMin,0);S.withdrawMin=mcnMoney(data.withdrawMin,0);S.withdrawFee=mcnMoney(data.withdrawFee,0);S.principalWithdrawable=data.principalWithdrawable==='on'||data.principalWithdrawable===true;S.version=uid('WPSET');}
 else if(action==='dailyRun'){const nr=wpNextRun(),day=data.supplement?nr.last:nr.day,run=wpDailyRun(day,backend?'管理员 '+actor+' 执行':actor==='演示工具'?'演示工具 · 模拟 00:00 日结':actor);out=run.id;}
 else demand(false,'未知钱包操作');
 wpSync();wpLog(action,out,reason,actor);return out;}
const WP_MSG={rechargeCreate:()=>'充值订单已生成，请按页面地址完成模拟转账',rechargeResult:id=>({已到账:'充值到账',充值失败:'充值失败，可以重新发起',结果未知:'充值结果未知，请稍后查询原请求'})[wpDB().recharges.find(r=>r.id===id)?.status]||'充值状态已更新',rechargeCancel:()=>'充值订单已取消',withdrawCreate:()=>'提现申请已提交，等待平台审核',withdrawCancel:()=>'提现申请已撤销，金额已解冻',withdrawReview:()=>'提现已审核，等待出款',withdrawSubmit:()=>'已提交模拟出款，请查询原请求结果',withdrawResult:id=>({已到账:'提现已到账',明确失败:'出款明确失败，可重新提交或驳回',结果未知:'出款结果未知，请稍后查询原请求'})[wpDB().withdrawals.find(w=>w.id===id)?.status]||'出款状态已更新',settings:()=>'钱包设置已保存',dailyRun:id=>{const r=wpDB().runs.find(x=>x.id===id);return r?`${r.day} 00:00 日结完成${r.supplement?'（补跑）':''}：${r.count} 笔分红，合计 ${wpU(r.total)}`:'日结完成';}};
function wpRun(action,id,data={},backend=false){V23.flashErr=false;try{const out=v22Persist(()=>wpCommand(action,id,data,backend));mcnCloseDialog();const msg=WP_MSG[action]?.(out,data);
 if(backend||FE.mode==='admin'){toast(msg||'已保存');render();return out;}
 if(action==='pay'){feRender();return out;}
 if(action==='rechargeCreate')feNavigate('walletRecharge',FE.id||'');
 FE.flash=msg||'已保存';feRender();return out;}catch(err){V23.flashErr=true;throw err;}}
function wpBtn(action,label,id='',values={},cls='small',backend=false){return `<button type="button" class="${backend?'btn small':'fe-btn '+cls}" data-wp-command="${e(action)}" data-id="${e(id)}" data-values="${e(JSON.stringify(values))}" ${backend?'data-wp-backend="true"':''}>${label}</button>`;}
function wpForm(action,id,body,label,backend=false,cls='primary'){return `<form class="mcn-form" data-wp-form="${e(action)}" data-id="${e(id)}" ${backend?'data-wp-backend="true"':''}>${body}<div class="mcn-form-error" role="alert"></div><button class="${backend?'btn primary':'fe-btn '+cls}" type="submit">${e(label)}</button></form>`;}
function wpOpen(action,id,values={},backend=false){const reason=mcnField('reason','处理依据（至少4字）','核对钱包记录与原请求');
 if(action==='withdrawReview')return mcnDialog('审核提现',wpForm('withdrawReview',id,reason,'通过审核',true));
 if(action==='withdrawCancel')return mcnDialog(backend?'驳回提现':'撤销提现',wpForm('withdrawCancel',id,backend?mcnField('reason','驳回原因（至少4字）',''):'<p>撤销后冻结金额立即解冻。</p>',backend?'确认驳回':'确认撤销',backend));
 demand(false,'未知操作');}
document.addEventListener('click',ev=>{const b=ev.target.closest?.('[data-wp-command],[data-wp-open]');if(!b||b.disabled)return;ev.preventDefault();try{const data=JSON.parse(b.dataset.values||'{}'),backend=b.dataset.wpBackend==='true';if(b.dataset.wpOpen)return wpOpen(b.dataset.wpOpen,b.dataset.id||'',data,backend);wpRun(b.dataset.wpCommand,b.dataset.id||'',data,backend);}catch(err){if(FE.mode==='admin')toast(err.message,'error');else{V23.flashErr=true;FE.flash=err.message;feRender();}}});
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.dataset?.wpForm)return;ev.preventDefault();if(!f.reportValidity())return;try{wpRun(f.dataset.wpForm,f.dataset.id||'',Object.fromEntries(new FormData(f)),f.dataset.wpBackend==='true');}catch(err){const box=f.querySelector('.mcn-form-error');if(box)box.textContent=err.message;}});

