const wpMcnCommandBase=mcnCommand;
mcnCommand=function(action,id='',data={},backend=false){if(action!=='settings')return wpMcnCommandBase(action,id,data,backend);const s=mcnDB().settings,input={...data};
 for(const k of ['depositRequired','claimMax','withdrawMin','minSpend','guildDefaultPct','guildMaxPct','contractDays','bindingDays','settlementDays','coolingDays'])if(input[k]===undefined)input[k]=s[k];
 if(input.validDays===undefined)input.validDays=input.bindingDays;if(input.sourceService===undefined)input.sourceService=true;
 const threshold=input.rechargeThreshold===undefined?s.rechargeThreshold:mcnMoney(input.rechargeThreshold,0,10000000),source=input.dividendSource===undefined?s.dividendSource:input.dividendSource==='all'?'all':'wallet';
 const out=wpMcnCommandBase(action,id,input,backend);Object.assign(mcnDB().settings,{rechargeThreshold:threshold,dividendSource:source});mcnEvaluateReferrals();return out;};
const wpExitListBase=mcnxExitChecklist;mcnxExitChecklist=g=>wpExitListBase(g).filter(([t])=>t!=='机构推广收益已结清');

